from pathlib import Path
import json,pandas as pd
out=Path('MER_VIS_pipeline_v2/current_report/comparison');s=json.loads((out/'summary.json').read_text());m=pd.read_csv(out/'galaxy_by_galaxy_comparison.csv');common=m.codex_fit_status.eq('provisional_fit')&m.status.eq('ok');review=m.loc[common&m[['disc_PA_delta_deg','bar_PA_delta_deg','inclination_delta_deg']].abs().gt(20).any(axis=1)];review.to_csv(out/'large_differences_for_review.csv',index=False)
lines=['# MER VIS geometry compared with the supplied method','','20 October 2026','','This compares the current measurements and quality classifications with the separately supplied fitted table. All 2777 object IDs match. Missing bar measurements are excluded rather than replaced with zero. This document contains no comparison with earlier pipeline versions.','','| Subset | Disc PA median absolute difference | Bar PA median absolute difference | Inclination median absolute difference |','|---|---:|---:|---:|']
for label,key in [('All common measurements','common'),('Current measurements with no counted flags','codex_revised_unflagged'),('Neither table has counted flags','both_unflagged')]:
 z=s['statistics'][key];lines.append('| '+label+' | '+' | '.join(f"{z[c]['median_abs']:.2f}° (n={z[c]['n']})" if z[c]['n'] else 'Unavailable' for c in ['disc_PA_delta_deg','bar_PA_delta_deg','inclination_delta_deg'])+' |')
lines+=['','PA is North towards East modulo 180°. Signed axial differences wrap into [-90°,90°). No additional 90° adjustment is applied to the supplied fitted angles; the adopted +90° applies only to the Euclid detection-catalogue comparison.','','Our inclination uses a circular thin disc (q0=0); the supplied method uses q0=0.2. These are consistency comparisons using the same images and Photutils, not independent accuracy measurements.','','The no-counted-flags subsets use the current sparse-sampling and radial-PA-variation rules. Adjacent ellipse samples are correlated. Nearly-face-on discs are informational and exempt from both PA review flags.','',f'{len(review)} common-fit objects differ by over 20° in at least one available quantity. See large_differences_for_review.csv. The joined CSV retains all current values, catalogue names, flags and signed differences.']
(out/'comparison_summary.md').write_text('\n'.join(lines),encoding='utf8')
